40	/**
41	 * Fragment-only helpers (use screen-space derivatives, so never include in a vertex shader).
42	 *  - bumpNormal: Mikkelsen-style "bump mapping without tangents" from a scalar height field
43	 *  - starGlint:  4-point star glint anchored to a world-space cell grid but sized in PIXELS, so the
44	 *                cross stays star-shaped under grazing foreshortening (refs 05–07 white glints)
45	 */
46	export const FRAG_FX_GLSL = /* glsl */ `
47	vec3 bumpNormal(vec3 pos, vec3 n, float h) {
48	  vec3 dpx = dFdx(pos);
49	  vec3 dpy = dFdy(pos);
50	  float dhx = dFdx(h);
51	  float dhy = dFdy(h);
52	  vec3 r1 = cross(dpy, n);
53	  vec3 r2 = cross(n, dpx);
54	  float det = dot(dpx, r1);
55	  vec3 grad = sign(det) * (dhx * r1 + dhy * r2);
56	  return normalize(abs(det) * n - grad);
57	}
58	// g: cell coordinates (world-anchored); density: probability a cell holds a star; L: arm length px;
59	// stretch: horizontal (g.x) arm length relative to the vertical one (ref 05 glints are wide flares)
60	float starGlint(vec2 g, float density, float L, float stretch, float time) {
61	  vec2 gi = floor(g);
62	  float hs = hash12(gi + 7.31);
63	  if (hs < 1.0 - density) return 0.0;
64	  vec2 cpp = max(fwidth(g), vec2(1e-4));           // cells per pixel
65	  vec2 c = vec2(hash12(gi + 3.1), hash12(gi + 5.7)) * 0.5 + 0.25;
66	  vec2 px = (fract(g) - c) / cpp;                   // offset in pixels
67	  vec2 lim = 0.24 / cpp;                            // never cross the cell border
68	  float l = L * (0.55 + 0.9 * fract(hs * 37.0));
69	  float ax = exp(-abs(px.y) * 0.75) * max(0.0, 1.0 - abs(px.x) / min(l * stretch, lim.x));
70	  float ay = exp(-abs(px.x) * 0.8) * max(0.0, 1.0 - abs(px.y) / min(l, lim.y));
71	  float core = exp(-dot(px, px) * 0.05) * 1.6;
72	  float tw = 0.55 + 0.45 * pow(0.5 + 0.5 * sin(time * 5.0 + hs * 60.0), 2.0);
73	  return ((ax * ax + ay * ay) * 1.6 + core) * tw;
74	}
75	// 4-point flare on a FLOW-aligned cell grid g = (across-flow, along-flow) cell coordinates (world-anchored,
76	// advected). The pixel offset from the star centre is solved through the screen Jacobian of g, and the
77	// long arm is laid along the SCREEN direction of +g.y (the current), so the flares streak with the flow
78	// on every bend (ref 05 mid-field) instead of collapsing into horizontal dashes under grazing
79	// foreshortening. horiz 0..1 turns the long arm toward screen-horizontal (ref 05 near-field flares lie
80	// across the flow). Arms taper to zero before the cell border (no clipped arms). Derivatives are taken
81	// before any early-out (Android-safe).
82	float flowGlint(vec2 g, float density, float L, float stretch, float horiz, float time) {
83	  vec2 gx = dFdx(g);
84	  vec2 gy = dFdy(g);
85	  vec2 gi = floor(g);
86	  float hs = hash12(gi + 7.31);
87	  float det = gx.x * gy.y - gy.x * gx.y;
88	  if (hs < 1.0 - density || abs(det) < 1e-12) return 0.0;
89	  vec2 dg = fract(g) - (vec2(hash12(gi + 3.1), hash12(gi + 5.7)) * 0.2 + 0.4);
90	  vec2 p = vec2(gy.y * dg.x - gy.x * dg.y, gx.x * dg.y - gx.y * dg.x) / det;   // pixels
91	  vec2 f = vec2(-gy.x, gx.x);                    // screen direction of +g.y (unnormalised, sign-free)
92	  f *= sign(f.x + 1e-6) / max(length(f), 1e-9);
93	  vec2 a = normalize(mix(f, vec2(1.0, 0.0), horiz) + vec2(1e-5, 0.0));
94	  vec2 b = vec2(-a.y, a.x);
95	  float pa = dot(p, a), pb = dot(p, b);
96	  vec2 ca = a.x * gx + a.y * gy, cb = b.x * gx + b.y * gy;   // cell units per pixel along a / b
97	  float la = 0.38 / max(max(abs(ca.x), abs(ca.y)), 1e-6);
98	  float lb = 0.38 / max(max(abs(cb.x), abs(cb.y)), 1e-6);
99	  float l = L * (0.55 + 0.9 * fract(hs * 37.0));
100	  float tA = max(0.0, 1.0 - abs(pa) / min(l * stretch, la));
101	  float armA = exp(-abs(pb) * 0.85) * tA;
102	  float armB = exp(-abs(pa) * 0.85) * max(0.0, 1.0 - abs(pb) / min(l, lb));
103	  // (wave 7) small hot core (≈2 px): the old wide soft core (exp(-r²·0.06)) read as round snow dots
104	  float core = exp(-dot(p, p) * 0.22) * 1.4;
105	  // (wave 8) soft glow lying along the long arm (≈5 px wide, tapering): ref 05 flares are thick glowing
106	  // streaks, the bare 1-px arms read as thin wire crosses (the game's bloom is weak)
107	  float glowA = exp(-abs(pb) * 0.2) * tA * tA * 0.3;
108	  float tw = 0.55 + 0.45 * pow(0.5 + 0.5 * sin(time * 5.0 + hs * 60.0), 2.0);
109	  return ((armA * armA + armB * armB) * 1.6 + core + glowA) * tw;
110	}
111	// Lens-shaped glossy flare (ref 05 near field): a bright streak lying along SCREEN-horizontal, thick in
112	// the middle and tapering to points (half thickness T·(1 − x²)), slightly arched, with a soft glow.
113	// g = world-anchored, advected cell grid; Lpx / Tpx = half length / half thickness in pixels (clamped so
114	// the lens never crosses its cell border). Returns ≈1 on the white core, a fraction in the glow.
115	// Derivatives are taken before the early-out (Android-safe).
116	float lensFlare(vec2 g, float density, float Lpx, float Tpx, float time) {
117	  vec2 gx = dFdx(g);
118	  vec2 gy = dFdy(g);
119	  vec2 gi = floor(g);
120	  float hs = hash12(gi + 4.17);
121	  float det = gx.x * gy.y - gy.x * gx.y;
122	  if (hs < 1.0 - density || abs(det) < 1e-12) return 0.0;
123	  vec2 dg = fract(g) - (vec2(hash12(gi + 2.3), hash12(gi + 6.9)) * 0.3 + 0.35);
124	  vec2 p = vec2(gy.y * dg.x - gy.x * dg.y, gx.x * dg.y - gx.y * dg.x) / det;   // pixels
125	  float limx = 0.3 / max(abs(gx.x) + abs(gx.y), 1e-6);
126	  float limy = 0.3 / max(abs(gy.x) + abs(gy.y), 1e-6);
127	  float L = min(Lpx * (0.55 + 0.9 * fract(hs * 37.0)), limx);
128	  float T = min(Tpx * (0.7 + 0.6 * fract(hs * 53.0)), limy * 0.5);
129	  float x = p.x / L;
130	  if (abs(x) > 1.0) return 0.0;
131	  float y = p.y - 0.35 * T * (1.0 - x * x);       // slight arch
132	  float th = T * (1.0 - x * x);
133	  float lens = 1.0 - smoothstep(th * 0.6, th + 1.0, abs(y));
134	  float glow = exp(-abs(y) / (T * 2.2 + 1.0)) * (1.0 - abs(x));
135	  float tw = 0.75 + 0.25 * sin(time * 3.0 + hs * 40.0);
136	  return (lens + 0.7 * glow) * tw;
137	}
138	`;
