from PIL import Image, ImageFilter


def uniform_filter(L, k):
    r = k // 2
    p = np.pad(L, r + 1, mode="edge").astype(np.float64)
    c = p.cumsum(0).cumsum(1)
    H, W = L.shape
    s = (c[k:k + H, k:k + W] - c[0:H, k:k + W] - c[k:k + H, 0:W] + c[0:H, 0:W])
    return (s / (k * k)).astype(np.float32)


def maximum_filter(L, k):
    im = Image.fromarray(np.clip(L, 0, 255).astype(np.uint8))
    return np.asarray(im.filter(ImageFilter.MaxFilter(k))).astype(np.float32)

