def lum(a):
    # wave-8 m05 used the plain RGB mean (reproduces its ref near p5/p50/p95/std 120.3/145.3/246.3/36.6)
    return a.mean(axis=2)


def blobs(mask, amin=2, amax=600):
    """count 8-connected components of mask with amin <= area <= amax (sparse BFS, no scipy)"""
    H, W = mask.shape
    seen = np.zeros_like(mask, dtype=bool)
    ys, xs = np.nonzero(mask)
    n = 0
    for y0, x0 in zip(ys, xs):
        if seen[y0, x0]:
            continue
        stack = [(y0, x0)]
        seen[y0, x0] = True
        area = 0
        while stack:
            y, x = stack.pop()
            area += 1
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < H and 0 <= xx < W and mask[yy, xx] and not seen[yy, xx]:
                        seen[yy, xx] = True
                        stack.append((yy, xx))
        if amin <= area <= amax:
            n += 1
    return n

