#!/usr/bin/env python3
"""Forward/inverse model of the game's colour chain (no bloom, no vignette):
shader linear RGB -> x exposure 0.86 -> three.js NeutralToneMapping -> sRGB -> grade (sat 1.36 about Rec.709 luma,
contrast 1.15 about 0.5, clamp).  usage: chain.py fwd r g b | chain.py inv '#RRGGBB'"""
import sys
import numpy as np

EXP, SAT, CON = 0.86, 1.36, 1.15


def neutral(c):
    c = np.array(c, float)
    sc, des = 0.8 - 0.04, 0.15
    x = c.min()
    off = x - 6.25 * x * x if x < 0.08 else 0.04
    c = c - off
    peak = c.max()
    if peak < sc:
        return c
    d = 1 - sc
    np_ = 1 - d * d / (peak + d - sc)
    c = c * (np_ / peak)
    g = 1 - 1 / (des * (peak - np_) + 1)
    return c * (1 - g) + np_ * g


def srgb(c):
    c = np.clip(c, 0, 1)
    return np.where(c <= 0.0031308, 12.92 * c, 1.055 * np.power(c, 1 / 2.4) - 0.055)


def grade(c):
    l = c @ np.array([0.2126, 0.7152, 0.0722])
    c = l + (c - l) * SAT
    c = (c - 0.5) * CON + 0.5
    return np.clip(c, 0, 1)


def fwd(lin):
    return grade(srgb(neutral(np.array(lin, float) * EXP)))


def hexs(c):
    return "#%02X%02X%02X" % tuple(int(round(v * 255)) for v in c)


def inv(target_hex):
    t = np.array([int(target_hex[i:i + 2], 16) / 255 for i in (1, 3, 5)])
    x = np.array([0.3, 0.3, 0.3])
    for _ in range(4000):
        f = fwd(x)
        e = f - t
        J = np.zeros((3, 3))
        for k in range(3):
            dx = np.zeros(3); dx[k] = 1e-4
            J[:, k] = (fwd(x + dx) - f) / 1e-4
        step = np.linalg.lstsq(J + 1e-6 * np.eye(3), e, rcond=None)[0]
        x = np.clip(x - 0.5 * step, 0, 4)
    return x, fwd(x)


if __name__ == "__main__":
    if sys.argv[1] == "fwd":
        v = [float(a) for a in sys.argv[2:5]]
        print(hexs(fwd(v)))
    else:
        for h in sys.argv[2:]:
            x, f = inv(h)
            print(h, "->", "(%.3f, %.3f, %.3f)" % tuple(x), "renders", hexs(f))

