// base sat mid-ladder and the streak glow + bloom (≈ +8 lum) lifted the median to #2FC4FF vs ref #05B3FB):
// the deep lanes show between the streaks, the glowing streaks carry the brightness
float t5 = 0.3 + lane * 2.4;
